import os
from pathlib import Path

def db_path() -> Path:
    return Path(os.environ.get("APP_DB", "var/app.sqlite"))

def tenant_header() -> str:
    return os.environ.get("APP_TENANT_HEADER", "X-Tenant")

import argparse
from fastapi import FastAPI, Header, HTTPException, Response
from pydantic import BaseModel, Field
from app.config import tenant_header
from app.store import orders, refunds
from app.store.db import connect, migrate
from app.rules import order_rules

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class RefundIn(BaseModel):
    refund_id: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    reason: str = Field(default="")

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="", alias=None)) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    try:
        order = orders.add_payment(x_tenant, order_id, body.amount_cents)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/refunds", status_code=201)
def create_refund(body: RefundIn, x_tenant: str = Header(default=""),
                  idempotency_key: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    if not idempotency_key:
        raise HTTPException(status_code=400, detail="idempotency-key header is required")
    outcome = refunds.accept(x_tenant, body.refund_id, body.order_id,
                             body.amount_cents, body.reason, idempotency_key)
    return _render(outcome)

@app.get("/refunds/{refund_id}")
def read_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    refund = refunds.get(x_tenant, refund_id)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/reverse", status_code=200)
def reverse_refund(refund_id: str, x_tenant: str = Header(default=""),
                   idempotency_key: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    if not idempotency_key:
        raise HTTPException(status_code=400, detail="idempotency-key header is required")
    outcome = refunds.reverse(x_tenant, refund_id, idempotency_key)
    return _render(outcome)

def _render(outcome: refunds.Outcome) -> dict:
    if outcome.code != "ok":
        raise HTTPException(status_code=outcome.status, detail=outcome.detail)
    return outcome.body

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

import sqlite3
from app.store.db import connect

def insert(tenant: str, order_id: str, amount_cents: int, currency: str) -> None:
    conn = connect()
    try:
        conn.execute(
            "INSERT INTO orders(tenant, order_id, amount_cents, paid_cents, currency, status) VALUES(?,?,?,0,?,'accepted')",
            (tenant, order_id, amount_cents, currency),
        )
    finally:
        conn.close()

def get(tenant: str, order_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, order_id, amount_cents, paid_cents, currency, status FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    outstanding = row["amount_cents"] - row["paid_cents"]
    return {**dict(row), "outstanding_cents": outstanding}

def add_payment(tenant: str, order_id: str, amount_cents: int) -> dict | None:
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if amount_cents <= 0 or row["paid_cents"] + amount_cents > row["amount_cents"]:
            conn.execute("ROLLBACK")
            raise ValueError("payment exceeds outstanding amount")
        conn.execute(
            "UPDATE orders SET paid_cents = paid_cents + ?, status = CASE WHEN paid_cents + ? >= amount_cents THEN 'settled' ELSE 'accepted' END WHERE tenant=? AND order_id=?",
            (amount_cents, amount_cents, tenant, order_id),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return get(tenant, order_id)

import json
import sqlite3
from dataclasses import dataclass
from datetime import UTC, datetime

from app.store.db import connect

# Refund lifecycle: pending -> effective -> reversed (terminal).
# pending and effective refunds occupy the order's refundable quota;
# reversed refunds release it.
PENDING = "pending"
EFFECTIVE = "effective"
REVERSED = "reversed"

# Outcome codes let the HTTP layer distinguish error classes without
# parsing free-text messages.
NOT_FOUND = "not_found"
QUOTA = "quota_exceeded"
CONFLICT = "conflict"


@dataclass
class Outcome:
    code: str
    status: int
    detail: str
    body: dict

    @classmethod
    def ok(cls, body: dict) -> "Outcome":
        return cls("ok", 200, "", body)

    @classmethod
    def created(cls, body: dict) -> "Outcome":
        return cls("ok", 201, "", body)


def _now() -> str:
    return datetime.now(UTC).isoformat()


def _serialize(refund: dict | None, status: int) -> str:
    return json.dumps({"status": status, "detail": "", "body": refund}, ensure_ascii=False)


def _deserialize(raw: str) -> tuple[int, str, dict | None]:
    payload = json.loads(raw)
    return payload["status"], payload["detail"], payload["body"]


def _row_to_dict(row: sqlite3.Row) -> dict:
    return {
        "refund_id": row["refund_id"],
        "order_id": row["order_id"],
        "amount_cents": row["amount_cents"],
        "reason": row["reason"],
        "status": row["status"],
        "created_at": row["created_at"],
    }


def get(tenant: str, refund_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, reason, status, created_at "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
    finally:
        conn.close()
    return None if row is None else _row_to_dict(row)


def accept(tenant: str, refund_id: str, order_id: str, amount_cents: int,
           reason: str, fingerprint: str) -> Outcome:
    """Accept a refund idempotently.

    Refundable quota = order.paid_cents - SUM(amount) of pending/effective
    refunds. A replayed request (same tenant/operation/target/fingerprint)
    returns the original result regardless of current quota.
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")

        replay = _lookup_replay(conn, tenant, "accept", refund_id, fingerprint)
        if replay is not None:
            conn.execute("COMMIT")
            return replay

        order = conn.execute(
            "SELECT amount_cents, paid_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            return _record_and_finish(
                conn, tenant, "accept", refund_id, fingerprint,
                404, NOT_FOUND, "refund target not found",
            )

        existing = conn.execute(
            "SELECT 1 FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if existing is not None:
            return _record_and_finish(
                conn, tenant, "accept", refund_id, fingerprint,
                409, CONFLICT, "refund already accepted",
            )

        occupied = conn.execute(
            "SELECT COALESCE(SUM(amount_cents),0) AS s FROM refunds "
            "WHERE tenant=? AND order_id=? AND status IN (?,?)",
            (tenant, order_id, PENDING, EFFECTIVE),
        ).fetchone()["s"]
        refundable = order["paid_cents"] - occupied

        # A positive amount that also fits the refundable quota necessarily
        # fits the order amount; the order-amount cap is checked explicitly
        # to make the boundary explicit.
        if amount_cents <= 0 or amount_cents > order["amount_cents"]:
            return _record_and_finish(
                conn, tenant, "accept", refund_id, fingerprint,
                400, "invalid_amount", "refund amount must be a positive integer not exceeding order amount",
            )
        if amount_cents > refundable:
            return _record_and_finish(
                conn, tenant, "accept", refund_id, fingerprint,
                409, QUOTA, "refund exceeds refundable amount",
            )

        created_at = _now()
        conn.execute(
            "INSERT INTO refunds(tenant, refund_id, order_id, amount_cents, reason, status, created_at) "
            "VALUES(?,?,?,?,?,?,?)",
            (tenant, refund_id, order_id, amount_cents, reason, PENDING, created_at),
        )
        body = {
            "refund_id": refund_id,
            "order_id": order_id,
            "amount_cents": amount_cents,
            "reason": reason,
            "status": PENDING,
            "created_at": created_at,
        }
        _store_outcome(conn, tenant, "accept", refund_id, fingerprint, "ok", 201, "", _serialize(body, 201))
        conn.execute("COMMIT")
        return Outcome.created(body)
    finally:
        conn.close()


def reverse(tenant: str, refund_id: str, fingerprint: str) -> Outcome:
    """Reverse a refund idempotently, releasing its occupied quota atomically."""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")

        replay = _lookup_replay(conn, tenant, "reverse", refund_id, fingerprint)
        if replay is not None:
            conn.execute("COMMIT")
            return replay

        row = conn.execute(
            "SELECT order_id, amount_cents, reason, status, created_at FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if row is None:
            return _record_and_finish(
                conn, tenant, "reverse", refund_id, fingerprint,
                404, NOT_FOUND, "refund not found",
            )

        if row["status"] == REVERSED:
            return _record_and_finish(
                conn, tenant, "reverse", refund_id, fingerprint,
                409, CONFLICT, "refund already reversed",
            )

        conn.execute(
            "UPDATE refunds SET status=? WHERE tenant=? AND refund_id=?",
            (REVERSED, tenant, refund_id),
        )
        body = {
            "refund_id": refund_id,
            "order_id": row["order_id"],
            "amount_cents": row["amount_cents"],
            "reason": row["reason"],
            "status": REVERSED,
            "created_at": row["created_at"],
        }
        _store_outcome(conn, tenant, "reverse", refund_id, fingerprint, "ok", 200, "", _serialize(body, 200))
        conn.execute("COMMIT")
        return Outcome.ok(body)
    finally:
        conn.close()


def _lookup_replay(conn: sqlite3.Connection, tenant: str, operation: str,
                   target_id: str, fingerprint: str) -> Outcome | None:
    row = conn.execute(
        "SELECT result_code, result_status, result_detail, result_body "
        "FROM idempotent_requests WHERE tenant=? AND operation=? AND target_id=? AND request_fingerprint=?",
        (tenant, operation, target_id, fingerprint),
    ).fetchone()
    if row is None:
        return None
    status, detail, body = _deserialize(row["result_body"])
    return Outcome(row["result_code"], status, detail, body if body is not None else {})


def _store_outcome(conn: sqlite3.Connection, tenant: str, operation: str, target_id: str,
                   fingerprint: str, code: str, status: int, detail: str, body: str) -> None:
    conn.execute(
        "INSERT INTO idempotent_requests(tenant, operation, target_id, request_fingerprint, "
        "result_code, result_status, result_detail, result_body, created_at) "
        "VALUES(?,?,?,?,?,?,?,?,?)",
        (tenant, operation, target_id, fingerprint, code, status, detail, body, _now()),
    )


def _record_and_finish(conn: sqlite3.Connection, tenant: str, operation: str, target_id: str,
                       fingerprint: str, status: int, code: str, detail: str) -> Outcome:
    """Persist a terminal (non-2xx) outcome for replay, then commit."""
    _store_outcome(conn, tenant, operation, target_id, fingerprint,
                   code, status, detail, json.dumps(
                       {"status": status, "detail": detail, "body": None}, ensure_ascii=False))
    conn.execute("COMMIT")
    return Outcome(code, status, detail, {})

import os, tempfile
os.environ.setdefault("APP_DB", os.path.join(tempfile.mkdtemp(), "test.sqlite"))
from fastapi.testclient import TestClient
from app.entry import app
from app.store.db import migrate

migrate()
client = TestClient(app)

def test_accept_and_read_order() -> None:
    body = {"tenant": "t1", "order_id": "o1", "amount_cents": 500, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    got = client.get("/orders/o1", headers={"X-Tenant": "t1"})
    assert got.status_code == 200 and got.json()["outstanding_cents"] == 500

def test_duplicate_is_refused() -> None:
    body = {"tenant": "t1", "order_id": "o2", "amount_cents": 100, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    assert client.post("/orders", json=body).status_code == 409

def test_cross_tenant_read_is_not_found() -> None:
    body = {"tenant": "t1", "order_id": "o3", "amount_cents": 100, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.get("/orders/o3", headers={"X-Tenant": "t2"}).status_code == 404

def test_payment_cannot_exceed_outstanding() -> None:
    body = {"tenant": "t1", "order_id": "o4", "amount_cents": 300, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.post("/orders/o4/payments", json={"amount_cents": 100}, headers={"X-Tenant": "t1"}).status_code == 200
    assert client.post("/orders/o4/payments", json={"amount_cents": 500}, headers={"X-Tenant": "t1"}).status_code == 409

ALLOWED_CURRENCIES = {"CNY", "USD", "EUR", "JPY"}

def assert_currency(currency: str) -> None:
    if currency not in ALLOWED_CURRENCIES:
        raise ValueError("unsupported currency")

